 /// Prestations incluses / exclues / options (JSON structuré).\n  featuresJson        Json?\n  active              Boolean          @default(true)\n  sortOrder           Int              @default(0)\n  /// Schéma UI options (RS / WEB / ECOM…) — JSON OfferOptionSchema.\n  optionSchema        Json?\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @updatedAt\n\n  versions          CatalogOfferVersion[]\n  opportunities     CrmOpportunity[]\n  opportunityOffers CrmOpportunityOffer[]\n  quoteLines        ComQuoteLine[]\n  invoiceLines      ComInvoiceLine[]\n  contractLines     ComContractLine[]\n\n  @@index([pillar, active])\n  @@map(\"catalog_offers\")\n}\n\n/// Version immuable d’une offre (contrats / devis historiques).\nmodel CatalogOfferVersion {\n  id             String           @id @default(cuid())\n  catalogOfferId String\n  version        Int\n  isOfficial     Boolean          @default(false)\n  sku            String\n  name           String\n  description    String?\n  billing        CatalogBilling\n  priceMode      CatalogPriceMode\n  priceXof       Int?\n  floorPriceXof  Int?\n  vatEligible    Boolean          @default(true)\n  featuresJson   Json?\n  snapshotJson   Json\n  createdAt      DateTime         @default(now())\n\n  catalogOffer  CatalogOffer      @relation(fields: [catalogOfferId], references: [id], onDelete: Cascade)\n  contractLines ComContractLine[]\n\n  @@unique([catalogOfferId, version])\n  @@index([sku, version])\n  @@map(\"catalog_offer_versions\")\n}\n\nmodel CrmOrganization {\n  id             String     @id @default(cuid())\n  name           String\n  normalizedName String\n  sector         String?\n  city           String?\n  country        String     @default(\"ML\")\n  website        String?\n  /// LOT-F / P2-1 — réseaux sociaux entreprise (URLs).\n  instagramUrl   String?\n  linkedinUrl    String?\n  tiktokUrl      String?\n  facebookUrl    String?\n  whatsappUrl    String?\n  source         CrmSource?\n  notes          String?\n  ownerId        String     @db.Uuid\n  createdById    String     @db.Uuid\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  owner         User             @relation(\"CrmOrgOwner\", fields: [ownerId], references: [id])\n  createdBy     User             @relation(\"CrmOrgCreator\", fields: [createdById], references: [id])\n  contacts      CrmContact[]\n  opportunities CrmOpportunity[]\n  activities    CrmActivity[]\n  tasks         CrmTask[]\n  comClients    ComClient[]\n\n  @@index([ownerId])\n  @@index([normalizedName])\n  @@map(\"crm_organizations\")\n}\n\nmodel CrmContact {\n  id             String   @id @default(cuid())\n  organizationId String\n  firstName      String\n  lastName       String\n  jobTitle       String?\n  /// Miroir du canal principal EMAIL (compat listes / convert).\n  email          String?\n  /// Miroir du canal principal PHONE / WHATSAPP.\n  phone          String?\n  isPrimary      Boolean  @default(false)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization CrmOrganization     @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  channels     CrmContactChannel[]\n\n  @@index([organizationId])\n  @@index([email])\n  @@index([phone])\n  @@map(\"crm_contacts\")\n}\n\nmodel CrmContactChannel {\n  id              String                @id @default(cuid())\n  contactId       String\n  type            CrmContactChannelType\n  value           String\n  /// Valeur normalisée pour recherche doublons (digits tél / email lower).\n  normalizedValue String\n  isPrimary       Boolean               @default(false)\n  createdAt       DateTime              @default(now())\n  updatedAt       DateTime              @updatedAt\n\n  contact CrmContact @relation(fields: [contactId], references: [id], onDelete: Cascade)\n\n  @@index([contactId])\n  @@index([normalizedValue])\n  @@index([type, normalizedValue])\n  @@map(\"crm_contact_channels\")\n}\n\nmodel CrmOpportunity {\n  id              String           @id @default(cuid())\n  organizationId  String\n  title           String\n  stage           CrmPipelineStage @default(NOUVEAU)\n  source          CrmSource?\n  offerLabel      String?\n  catalogOfferId  String?\n  budgetXof       Int?\n  probability     Int? // 0..100\n  expectedCloseAt DateTime?\n  lossReason      CrmLossReason?\n  lossNote        String?\n  ownerId         String           @db.Uuid\n  createdById     String           @db.Uuid\n  lastActivityAt  DateTime?\n  nextAction      String?\n  followUpAt      DateTime?\n  wonAt           DateTime?\n  lostAt          DateTime?\n  /// Entrée en statut Intéressé — SLA devis 24h (GUIDE).\n  interestedAt    DateTime?        @map(\"interested_at\")\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  organization       CrmOrganization        @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  catalogOffer       CatalogOffer?          @relation(fields: [catalogOfferId], references: [id], onDelete: SetNull)\n  owner              User                   @relation(\"CrmDealOwner\", fields: [ownerId], references: [id])\n  createdBy          User                   @relation(\"CrmDealCreator\", fields: [createdById], references: [id])\n  activities         CrmActivity[]\n  tasks              CrmTask[]\n  appointments       CrmAppointment[]\n  opportunityOffers  CrmOpportunityOffer[]\n  comClients         ComClient[]\n  comQuotes          ComQuote[]\n  assignmentRequests CrmAssignmentRequest[]\n\n  @@index([ownerId, stage])\n  @@index([organizationId])\n  @@index([followUpAt])\n  @@map(\"crm_opportunities\")\n}\n\n/// Demande d’affectation du suivi (commercial → Direction / Admin CRM).\nmodel CrmAssignmentRequest {\n  id            String                     @id @default(cuid())\n  opportunityId String\n  requesterId   String                     @db.Uuid\n  message       String?\n  status        CrmAssignmentRequestStatus @default(PENDING)\n  createdAt     DateTime                   @default(now())\n  resolvedAt    DateTime?\n  resolvedById  String?                    @db.Uuid\n  resolveNote   String?\n\n  opportunity CrmOpportunity @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  requester   User           @relation(\"CrmAssignmentRequester\", fields: [requesterId], references: [id], onDelete: Cascade)\n  resolvedBy  User?          @relation(\"CrmAssignmentResolver\", fields: [resolvedById], references: [id], onDelete: SetNull)\n\n  @@index([status, createdAt])\n  @@index([opportunityId, status])\n  @@index([requesterId])\n  @@map(\"crm_assignment_requests\")\n}\n\n/// Offres proposées à un prospect (N:N) + config options.\nmodel CrmOpportunityOffer {\n  id             String   @id @default(cuid())\n  opportunityId  String\n  catalogOfferId String\n  config         Json?\n  sortOrder      Int      @default(0)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  opportunity  CrmOpportunity @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  catalogOffer CatalogOffer   @relation(fields: [catalogOfferId], references: [id], onDelete: Cascade)\n\n  @@unique([opportunityId, catalogOfferId])\n  @@index([opportunityId])\n  @@map(\"crm_opportunity_offers\")\n}\n\nmodel CrmActivity {\n  id             String          @id @default(cuid())\n  organizationId String?\n  opportunityId  String?\n  type           CrmActivityType\n  summary        String\n  body           String?\n  occurredAt     DateTime        @default(now())\n  actorId        String          @db.Uuid\n  createdAt      DateTime        @default(now())\n\n  organization CrmOrganization? @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  opportunity  CrmOpportunity?  @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  actor        User             @relation(\"CrmActivityActor\", fields: [actorId], references: [id])\n\n  @@index([opportunityId, occurredAt])\n  @@index([organizationId, occurredAt])\n  @@map(\"crm_activities\")\n}\n\nmodel CrmTask {\n  id             String        @id @default(cuid())\n  organizationId String?\n  opportunityId  String?\n  title          String\n  dueAt          DateTime\n  status         CrmTaskStatus @default(OPEN)\n  assigneeId     String        @db.Uuid\n  createdById    String        @db.Uuid\n  completedAt    DateTime?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n\n  organization CrmOrganization? @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  opportunity  CrmOpportunity?  @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  assignee     User             @relation(\"CrmTaskAssignee\", fields: [assigneeId], references: [id])\n  createdBy    User             @relation(\"CrmTaskCreator\", fields: [createdById], references: [id])\n\n  @@index([assigneeId, status, dueAt])\n  @@index([dueAt])\n  @@map(\"crm_tasks\")\n}\n\nmodel CrmAppointment {\n  id            String               @id @default(cuid())\n  opportunityId String\n  title         String\n  startsAt      DateTime\n  endsAt        DateTime?\n  location      String?\n  notes         String?\n  status        CrmAppointmentStatus @default(SCHEDULED)\n  assigneeId    String               @db.Uuid\n  createdById   String               @db.Uuid\n  completedAt   DateTime?\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n\n  opportunity CrmOpportunity @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  assignee    User           @relation(\"CrmAppointmentAssignee\", fields: [assigneeId], references: [id])\n  createdBy   User           @relation(\"CrmAppointmentCreator\", fields: [createdById], references: [id])\n\n  @@index([assigneeId, startsAt])\n  @@index([opportunityId, startsAt])\n  @@index([status, startsAt])\n  @@map(\"crm_appointments\")\n}\n\n/// Notifications in-app (écriture Prisma uniquement ; Realtime SELECT own).\nmodel AppNotification {\n  id          String    @id @default(cuid())\n  userId      String    @db.Uuid\n  title       String\n  body        String?\n  href        String?\n  kind        String\n  readAt      DateTime?\n  emailSentAt DateTime?\n  createdAt   DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, readAt, createdAt])\n  @@index([userId, createdAt])\n  @@map(\"app_notifications\")\n}\n\nmodel CrmScript {\n  id        String    @id @default(cuid())\n  code      String    @unique\n  channel   CrmSource\n  title     String\n  body      String\n  tips      String?\n  active    Boolean   @default(true)\n  sortOrder Int       @default(0)\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@index([channel, active])\n  @@map(\"crm_scripts\")\n}\n\n/// Objectifs CRM ancrés à une période (jour / semaine / mois).\nmodel CrmPeriodGoal {\n  id          String   @id @default(cuid())\n  /// USER = un collab ; TEAM = objectif pôle (userId null).\n  scope       String\n  userId      String?  @db.Uuid\n  /// NEW_PROSPECTS | FIRST_CONTACTS | MEETINGS | FOLLOW_UPS\n  metric      String\n  /// DAY | WEEK | MONTH\n  periodType  String\n  /// Début de période (UTC date) : jour ; lundi ISO ; 1er du mois.\n  periodStart DateTime @db.Date\n  target      Int\n  updatedAt   DateTime @updatedAt\n  createdAt   DateTime @default(now())\n\n  user User? @relation(\"CrmPeriodGoalUser\", fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([scope, userId, metric, periodType, periodStart])\n  @@index([scope, metric])\n  @@index([periodType, periodStart])\n  @@map(\"crm_period_goals\")\n}\n\n/// Rapport de semaine (vendredi) — chiffres préremplis + qualitatif.\nmodel CrmWeeklyReport {\n  id              String   @id @default(cuid())\n  authorId        String   @db.Uuid\n  /// Lundi 00:00 de la semaine concernée (UTC date).\n  weekStart       DateTime @db.Date\n  newProspects    Int      @default(0)\n  firstContacts   Int      @default(0)\n  replies         Int      @default(0)\n  inDiscussion    Int      @default(0)\n  qualified       Int      @default(0)\n  meetings        Int      @default(0)\n  followUpsDone   Int      @default(0)\n  difficulty      String?\n  needs           String?\n  scriptsFeedback String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  author User @relation(\"CrmWeeklyReportAuthor\", fields: [authorId], references: [id], onDelete: Cascade)\n\n  @@unique([authorId, weekStart])\n  @@index([weekStart])\n  @@map(\"crm_weekly_reports\")\n}\n\n/// Séquences documentaires — periodKey = YYYYMMDD (ou YYYY legacy).\nmodel ComNumberSequence {\n  id        String     @id @default(cuid())\n  kind      ComDocKind\n  periodKey String\n  lastValue Int        @default(0)\n  updatedAt DateTime   @updatedAt\n\n  @@unique([kind, periodKey])\n  @@map(\"com_number_sequences\")\n}\n\nmodel ComClient {\n  id                   String          @id @default(cuid())\n  name                 String\n  normalizedName       String\n  legalName            String?\n  clientType           ComClientType   @default(ENTREPRISE)\n  status               ComClientStatus @default(ACTIF)\n  sector               String?\n  /// Code dossier GED unique sous `03_CLIENTS` (évite collision nom → slug).\n  gedFolderCode        String          @unique\n  contactName          String?\n  contactRole          String?\n  email                String?\n  phone                String?\n  website              String?\n  address              String?\n  city                 String?\n  country              String          @default(\"ML\")\n  taxId                String?\n  notes                String?\n  includeTravelDefault Boolean         @default(false)\n  crmOrganizationId    String?\n  sourceOpportunityId  String?\n  ownerId              String          @db.Uuid\n  createdById          String          @db.Uuid\n  createdAt            DateTime        @default(now())\n  updatedAt            DateTime        @updatedAt\n\n  crmOrganization   CrmOrganization? @relation(fields: [crmOrganizationId], references: [id], onDelete: SetNull)\n  sourceOpportunity CrmOpportunity?  @relation(fields: [sourceOpportunityId], references: [id], onDelete: SetNull)\n  owner             User             @relation(\"ComClientOwner\", fields: [ownerId], references: [id])\n  createdBy         User             @relation(\"ComClientCreator\", fields: [createdById], references: [id])\n  quotes            ComQuote[]\n  invoices          ComInvoice[]\n  contracts         ComContract[]\n  payments          ComPayment[]\n  creditNotes       ComCreditNote[]\n  events            ComClientEvent[]\n\n  @@index([ownerId])\n  @@index([normalizedName])\n  @@index([crmOrganizationId])\n  @@index([status])\n  @@map(\"com_clients\")\n}\n\nmodel ComQuote {\n  id                String           @id @default(cuid())\n  /// Numéro officiel (null tant que brouillon non émis).\n  number            String?          @unique\n  draftCode         String           @unique\n  legacyNumber      String?\n  legacyInternalRef String?\n  status            ComQuoteStatus   @default(BROUILLON)\n  template          ComQuoteTemplate @default(LINE_ITEMS)\n  revision          Int              @default(1)\n  regime            ComDocRegime     @default(ML)\n  currency          String           @default(\"XOF\")\n  vatEnabled        Boolean          @default(true)\n  vatRate           Int              @default(18)\n  promoEnabled      Boolean          @default(false)\n  promoPercent      Int?\n  includeTravel     Boolean          @default(false)\n  object            String?\n  missionNote       String?\n  conditionsJson    Json?\n  validUntil        DateTime?\n  totalHt           Int              @default(0)\n  totalVat          Int              @default(0)\n  totalTtc          Int              @default(0)\n  clientId          String\n  opportunityId     String?\n  ownerId           String           @db.Uuid\n  createdById       String           @db.Uuid\n  gedDocumentId     String?\n  issuedAt          DateTime?\n  sentAt            DateTime?\n  acceptedAt        DateTime?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  client      ComClient       @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  opportunity CrmOpportunity? @relation(fields: [opportunityId], references: [id], onDelete: SetNull)\n  owner       User            @relation(\"ComQuoteOwner\", fields: [ownerId], references: [id])\n  createdBy   User            @relation(\"ComQuoteCreator\", fields: [createdById], references: [id])\n  lines       ComQuoteLine[]\n  invoices    ComInvoice[]\n  contracts   ComContract[]\n\n  /// Un seul devis lié par prospect (NULL autorisé plusieurs fois en PG).\n  @@unique([opportunityId])\n  @@index([clientId])\n  @@index([ownerId, status])\n  @@index([legacyNumber])\n  @@map(\"com_quotes\")\n}\n\nmodel ComQuoteLine {\n  id             String  @id @default(cuid())\n  quoteId        String\n  sortOrder      Int     @default(0)\n  label          String\n  description    String?\n  qty            Int     @default(1)\n  unitPrice      Int\n  catalogOfferId String?\n  isTravel       Boolean @default(false)\n  /// Snapshot optionnel au moment de la ligne.\n  snapshotJson   Json?\n\n  quote        ComQuote      @relation(fields: [quoteId], references: [id], onDelete: Cascade)\n  catalogOffer CatalogOffer? @relation(fields: [catalogOfferId], references: [id], onDelete: SetNull)\n\n  @@index([quoteId])\n  @@map(\"com_quote_lines\")\n}\n\nmodel ComContract {\n  id                String               @id @default(cuid())\n  reference         String               @unique\n  status            ComContractStatus    @default(BROUILLON)\n  title             String?\n  /// Famille document (analyse contrats §6.1) — pilote le template PDF.\n  family            ComContractFamily?\n  /// Nature de prestation — sélectionne les blocs de template (§6.1/§6.2).\n  serviceKind       ComServiceKind?\n  regime            ComDocRegime         @default(ML)\n  currency          String               @default(\"XOF\")\n  vatEnabled        Boolean              @default(true)\n  vatRate           Int                  @default(18)\n  billingDay        Int                  @default(5)\n  startDate         DateTime?\n  endDate           DateTime?\n  paymentTerms      String?\n  renewalTerms      String?\n  terminationTerms  String?\n  notes             String?\n  /// Origine de la composition commerciale (devis accepté vs saisie libre — Q3).\n  compositionSource ComCompositionSource @default(INLINE)\n  /// Périmètre famille B (contexte / objectifs / livrables / hors-périmètre…) — JSON libre (analyse §6.3 `scope`).\n  scopeJson         Json?\n  clientId          String\n  quoteId           String?\n  ownerId           String               @db.Uuid\n  createdById       String               @db.Uuid\n  signedAt          DateTime?\n  /// PDF contrat généré et classé en GED (P4).\n  gedDocumentId     String?\n  createdAt         DateTime             @default(now())\n  updatedAt         DateTime             @updatedAt\n\n  client    ComClient         @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  quote     ComQuote?         @relation(fields: [quoteId], references: [id], onDelete: SetNull)\n  owner     User              @relation(\"ComContractOwner\", fields: [ownerId], references: [id])\n  createdBy User              @relation(\"ComContractCreator\", fields: [createdById], references: [id])\n  lines     ComContractLine[]\n  invoices  ComInvoice[]\n\n  @@index([clientId, status])\n  @@index([ownerId])\n  @@map(\"com_contracts\")\n}\n\nmodel ComContractLine {\n  id                    String                @id @default(cuid())\n  contractId            String\n  sortOrder             Int                   @default(0)\n  label                 String\n  description           String?\n  qty                   Int                   @default(1)\n  unitPrice             Int\n  billing               CatalogBilling        @default(MONTHLY)\n  status                ComContractLineStatus @default(ACTIF)\n  startDate             DateTime?\n  endDate               DateTime?\n  nextBillAt            DateTime?\n  catalogOfferId        String?\n  catalogOfferVersionId String?\n  /// Snapshot immuable tarifs / conditions à la signature.\n  snapshotJson          Json\n  createdAt             DateTime              @default(now())\n  updatedAt             DateTime              @updatedAt\n\n  contract            ComContract          @relation(fields: [contractId], references: [id], onDelete: Cascade)\n  catalogOffer        CatalogOffer?        @relation(fields: [catalogOfferId], references: [id], onDelete: SetNull)\n  catalogOfferVersion CatalogOfferVersion? @relation(fields: [catalogOfferVersionId], references: [id], onDelete: SetNull)\n  invoiceLines        ComInvoiceLine[]\n\n  @@index([contractId, status])\n  @@index([nextBillAt])\n  @@map(\"com_contract_lines\")\n}\n\nmodel ComInvoice {\n  id                  String           @id @default(cuid())\n  /// Numéro officiel (null tant que brouillon).\n  number              String?          @unique\n  draftCode           String           @unique\n  legacyNumber        String?\n  legacyInternalRef   String?\n  status              ComInvoiceStatus @default(BROUILLON)\n  source              ComInvoiceSource @default(MANUAL)\n  regime              ComDocRegime     @default(ML)\n  currency            String           @default(\"XOF\")\n  vatEnabled          Boolean          @default(true)\n  vatRate             Int              @default(18)\n  object              String?\n  periodStart         DateTime?\n  periodEnd           DateTime?\n  dueDate             DateTime?\n  totalHt             Int              @default(0)\n  totalVat            Int              @default(0)\n  totalTtc            Int              @default(0)\n  /// Dénormalisé depuis allocations (cache).\n  amountPaid          Int              @default(0)\n  /// Net à payer présenté (période + arriérés affichés − acomptes sur doc).\n  presentedNetPayable Int?\n  clientId            String\n  quoteId             String?\n  contractId          String?\n  ownerId             String           @db.Uuid\n  createdById         String           @db.Uuid\n  gedDocumentId       String?\n  issuedAt            DateTime?\n  sentAt              DateTime?\n  importBatchId       String?\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @updatedAt\n\n  client      ComClient              @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  quote       ComQuote?              @relation(fields: [quoteId], references: [id], onDelete: SetNull)\n  contract    ComContract?           @relation(fields: [contractId], references: [id], onDelete: SetNull)\n  owner       User                   @relation(\"ComInvoiceOwner\", fields: [ownerId], references: [id])\n  createdBy   User                   @relation(\"ComInvoiceCreator\", fields: [createdById], references: [id])\n  importBatch ComImportBatch?        @relation(fields: [importBatchId], references: [id], onDelete: SetNull)\n  lines       ComInvoiceLine[]\n  payments    ComPayment[]\n  allocations ComPaymentAllocation[]\n  arrearsRefs ComInvoiceArrearsRef[] @relation(\"InvoiceArrearsOn\")\n  arrearsOf   ComInvoiceArrearsRef[] @relation(\"InvoiceArrearsSource\")\n  creditNotes ComCreditNote[]\n  reminders   ComInvoiceReminder[]\n\n  @@index([clientId])\n  @@index([ownerId, status])\n  @@index([contractId])\n  @@index([dueDate, status])\n  @@index([legacyNumber])\n  @@index([quoteId])\n  @@map(\"com_invoices\")\n}\n\nmodel ComInvoiceLine {\n  id             String  @id @default(cuid())\n  invoiceId      String\n  sortOrder      Int     @default(0)\n  label          String\n  description    String?\n  qty            Int     @default(1)\n  unitPrice      Int\n  catalogOfferId String?\n  contractLineId String?\n  isTravel       Boolean @default(false)\n  snapshotJson   Json?\n\n  invoice      ComInvoice       @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  catalogOffer CatalogOffer?    @relation(fields: [catalogOfferId], references: [id], onDelete: SetNull)\n  contractLine ComContractLine? @relation(fields: [contractLineId], references: [id], onDelete: SetNull)\n\n  @@index([invoiceId])\n  @@map(\"com_invoice_lines\")\n}\n\n/// Présentation d’arriéré sur une facture (pas une nouvelle créance).\nmodel ComInvoiceArrearsRef {\n  id              String  @id @default(cuid())\n  invoiceId       String\n  sourceInvoiceId String\n  presentedAmount Int\n  label           String?\n\n  invoice       ComInvoice @relation(\"InvoiceArrearsOn\", fields: [invoiceId], references: [id], onDelete: Cascade)\n  sourceInvoice ComInvoice @relation(\"InvoiceArrearsSource\", fields: [sourceInvoiceId], references: [id], onDelete: Restrict)\n\n  @@unique([invoiceId, sourceInvoiceId])\n  @@index([sourceInvoiceId])\n  @@map(\"com_invoice_arrears_refs\")\n}\n\nmodel ComCreditNote {\n  id            String    @id @default(cuid())\n  number        String?   @unique\n  draftCode     String    @unique\n  legacyNumber  String?\n  amount        Int\n  reason        String?\n  clientId      String\n  invoiceId     String\n  createdById   String    @db.Uuid\n  gedDocumentId String?\n  issuedAt      DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  client    ComClient  @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  invoice   ComInvoice @relation(fields: [invoiceId], references: [id], onDelete: Restrict)\n  createdBy User       @relation(\"ComCreditNoteCreator\", fields: [createdById], references: [id])\n\n  @@index([clientId])\n  @@index([invoiceId])\n  @@map(\"com_credit_notes\")\n}\n\nmodel ComPayment {\n  id            String           @id @default(cuid())\n  clientId      String\n  /// Conservé pour compat Phase 3 ; préférer allocations.\n  invoiceId     String?\n  amount        Int\n  method        ComPaymentMethod @default(VIREMENT)\n  status        ComPaymentStatus @default(VALIDATED)\n  paidAt        DateTime         @default(now())\n  reference     String?\n  note          String?\n  gedDocumentId String?\n  recordedById  String           @db.Uuid\n  importBatchId String?\n  createdAt     DateTime         @default(now())\n\n  client      ComClient              @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  invoice     ComInvoice?            @relation(fields: [invoiceId], references: [id], onDelete: SetNull)\n  recordedBy  User                   @relation(\"ComPaymentRecorder\", fields: [recordedById], references: [id])\n  importBatch ComImportBatch?        @relation(fields: [importBatchId], references: [id], onDelete: SetNull)\n  allocations ComPaymentAllocation[]\n\n  @@index([clientId])\n  @@index([invoiceId])\n  @@index([paidAt])\n  @@map(\"com_payments\")\n}\n\nmodel ComPaymentAllocation {\n  id        String   @id @default(cuid())\n  paymentId String\n  invoiceId String\n  amount    Int\n  createdAt DateTime @default(now())\n\n  payment ComPayment @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  invoice ComInvoice @relation(fields: [invoiceId], references: [id], onDelete: Restrict)\n\n  @@unique([paymentId, invoiceId])\n  @@index([invoiceId])\n  @@map(\"com_payment_allocations\")\n}\n\nmodel ComClientEvent {\n  id         String   @id @default(cuid())\n  clientId   String\n  type       String\n  summary    String\n  entityType String?\n  entityId   String?\n  metaJson   Json?\n  actorId    String?  @db.Uuid\n  createdAt  DateTime @default(now())\n\n  client ComClient @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  actor  User?     @relation(\"ComClientEventActor\", fields: [actorId], references: [id], onDelete: SetNull)\n\n  @@index([clientId, createdAt])\n  @@map(\"com_client_events\")\n}\n\nmodel ComInvoiceReminder {\n  id          String   @id @default(cuid())\n  invoiceId   String\n  level       Int      @default(1)\n  channel     String\n  content     String?\n  result      String?\n  nextAction  String?\n  sentAt      DateTime @default(now())\n  createdById String?  @db.Uuid\n\n  invoice ComInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId, sentAt])\n  @@map(\"com_invoice_reminders\")\n}\n\nmodel ComImportBatch {\n  id          String               @id @default(cuid())\n  label       String\n  status      ComImportBatchStatus @default(DRY_RUN)\n  sourceName  String?\n  reportJson  Json?\n  createdById String               @db.Uuid\n  committedAt DateTime?\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n\n  createdBy User               @relation(\"ComImportBatchCreator\", fields: [createdById], references: [id])\n  anomalies ComImportAnomaly[]\n  invoices  ComInvoice[]\n  payments  ComPayment[]\n\n  @@index([status])\n  @@map(\"com_import_batches\")\n}\n\nmodel ComImportAnomaly {\n  id        String                   @id @default(cuid())\n  batchId   String\n  code      String\n  severity  ComImportAnomalySeverity @default(WARNING)\n  message   String\n  entityRef String?\n  metaJson  Json?\n  resolved  Boolean                  @default(false)\n  createdAt DateTime                 @default(now())\n\n  batch ComImportBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  @@index([batchId, resolved])\n  @@map(\"com_import_anomalies\")\n}\n\n// ─── Phase 6 — Comptabilité SYSCOHADA + banques + budget ───\n\nenum CptAccountNature {\n  ASSET\n  LIABILITY\n  EQUITY\n  EXPENSE\n  INCOME\n}\n\nenum CptExerciseStatus {\n  OPEN\n  CLOSED\n}\n\nenum CptPeriodStatus {\n  OPEN\n  CLOSED\n}\n\nenum CptEntryStatus {\n  DRAFT\n  VALIDATED\n}\n\nenum BudNature {\n  CAPEX\n  OPEX\n}\n\nenum BudPatenteStatus {\n  PENDING\n  PAID\n  OVERDUE\n}\n\n/// Plan de comptes SYSCOHADA (minimal PME, extensible)\nmodel CptAccount {\n  id         String           @id @default(cuid())\n  code       String           @unique\n  label      String\n  classNum   Int\n  nature     CptAccountNature\n  isPostable Boolean          @default(true)\n  active     Boolean          @default(true)\n  parentId   String?\n  createdAt  DateTime         @default(now())\n  updatedAt  DateTime         @updatedAt\n\n  parent   CptAccount?      @relation(\"CptAccountTree\", fields: [parentId], references: [id], onDelete: SetNull)\n  children CptAccount[]     @relation(\"CptAccountTree\")\n  lines    CptEntryLine[]\n  banks    CptBankAccount[]\n\n  @@index([classNum, code])\n  @@index([active, isPostable])\n  @@map(\"cpt_accounts\")\n}\n\nmodel CptJournal {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  label     String\n  active    Boolean  @default(true)\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  entries CptEntry[]\n\n  @@map(\"cpt_journals\")\n}\n\nmodel CptExercise {\n  id        String            @id @default(cuid())\n  year      Int               @unique\n  status    CptExerciseStatus @default(OPEN)\n  createdAt DateTime          @default(now())\n  updatedAt DateTime          @updatedAt\n\n  periods CptPeriod[]\n\n  @@map(\"cpt_exercises\")\n}\n\nmodel CptPeriod {\n  id         String          @id @default(cuid())\n  exerciseId String\n  month      Int\n  status     CptPeriodStatus @default(OPEN)\n  createdAt  DateTime        @default(now())\n  updatedAt  DateTime        @updatedAt\n\n  exercise CptExercise @relation(fields: [exerciseId], references: [id], onDelete: Cascade)\n  entries  CptEntry[]\n\n  @@unique([exerciseId, month])\n  @@index([status])\n  @@map(\"cpt_periods\")\n}\n\nmodel CptEntry {\n  id               String         @id @default(cuid())\n  number           String         @unique\n  journalId        String\n  periodId         String\n  entryDate        DateTime       @db.Date\n  label            String\n  status           CptEntryStatus @default(DRAFT)\n  sourceType       String?\n  sourceId         String?\n  currencyOriginal String?\n  fxRate           Decimal?       @db.Decimal(12, 6)\n  amountOriginal   Int?\n  createdById      String         @db.Uuid\n  validatedById    String?        @db.Uuid\n  validatedAt      DateTime?\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  journal     CptJournal     @relation(fields: [journalId], references: [id])\n  period      CptPeriod      @relation(fields: [periodId], references: [id])\n  createdBy   User           @relation(\"CptEntryCreator\", fields: [createdById], references: [id])\n  validatedBy User?          @relation(\"CptEntryValidator\", fields: [validatedById], references: [id])\n  lines       CptEntryLine[]\n  bankTxns    CptBankTxn[]\n\n  @@index([journalId, entryDate])\n  @@index([periodId, status])\n  @@index([sourceType, sourceId])\n  @@map(\"cpt_entries\")\n}\n\nmodel CptEntryLine {\n  id        String  @id @default(cuid())\n  entryId   String\n  accountId String\n  label     String?\n  debit     Int     @default(0)\n  credit    Int     @default(0)\n  sortOrder Int     @default(0)\n\n  entry   CptEntry   @relation(fields: [entryId], references: [id], onDelete: Cascade)\n  account CptAccount @relation(fields: [accountId], references: [id])\n\n  @@index([entryId])\n  @@index([accountId])\n  @@map(\"cpt_entry_lines\")\n}\n\nmodel CptBankAccount {\n  id           String   @id @default(cuid())\n  code         String   @unique\n  label        String\n  bankName     String   @default(\"ECOBANK\")\n  accountRef   String?\n  currency     String   @default(\"XOF\")\n  cptAccountId String\n  active       Boolean  @default(true)\n  sortOrder    Int      @default(0)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  cptAccount CptAccount   @relation(fields: [cptAccountId], references: [id])\n  txns       CptBankTxn[]\n\n  @@index([active])\n  @@map(\"cpt_bank_accounts\")\n}\n\nmodel CptBankTxn {\n  id             String    @id @default(cuid())\n  bankAccountId  String\n  txnDate        DateTime  @db.Date\n  label          String\n  amount         Int\n  matchedEntryId String?\n  matchedAt      DateTime?\n  note           String?\n  createdById    String    @db.Uuid\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  bankAccount  CptBankAccount @relation(fields: [bankAccountId], references: [id], onDelete: Cascade)\n  matchedEntry CptEntry?      @relation(fields: [matchedEntryId], references: [id], onDelete: SetNull)\n  createdBy    User           @relation(\"CptBankTxnCreator\", fields: [createdById], references: [id])\n\n  @@index([bankAccountId, txnDate])\n  @@index([matchedEntryId])\n  @@map(\"cpt_bank_txns\")\n}\n\n/// Taux EUR → XOF (paramétrable)\nmodel CptFxRate {\n  id        String   @id @default(cuid())\n  pair      String   @default(\"EUR/XOF\")\n  rate      Decimal  @db.Decimal(12, 6)\n  validFrom DateTime @db.Date\n  note      String?\n  createdAt DateTime @default(now())\n\n  @@index([pair, validFrom])\n  @@map(\"cpt_fx_rates\")\n}\n\nmodel BudExercise {\n  id        String   @id @default(cuid())\n  year      Int      @unique\n  label     String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  lines    BudLine[]\n  patentes BudPatenteDue[]\n\n  @@map(\"bud_exercises\")\n}\n\nmodel BudLine {\n  id          String    @id @default(cuid())\n  exerciseId  String\n  nature      BudNature\n  category    String\n  month       Int\n  planned     Int       @default(0)\n  actual      Int       @default(0)\n  note        String?\n  createdById String    @db.Uuid\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  exercise  BudExercise @relation(fields: [exerciseId], references: [id], onDelete: Cascade)\n  createdBy User        @relation(\"BudLineCreator\", fields: [createdById], references: [id])\n\n  @@unique([exerciseId, nature, category, month])\n  @@index([exerciseId, month])\n  @@map(\"bud_lines\")\n}\n\n/// Suivi patente assisté (échéances + statut)\nmodel BudPatenteDue {\n  id         String           @id @default(cuid())\n  exerciseId String\n  label      String\n  dueDate    DateTime         @db.Date\n  amount     Int              @default(0)\n  status     BudPatenteStatus @default(PENDING)\n  note       String?\n  createdAt  DateTime         @default(now())\n  updatedAt  DateTime         @updatedAt\n\n  exercise BudExercise @relation(fields: [exerciseId], references: [id], onDelete: Cascade)\n\n  @@index([exerciseId, dueDate])\n  @@map(\"bud_patente_dues\")\n}\n\n// ─── Phase 4 — RH cœur ───\n\nenum RhEmployeeType {\n  SALARIE\n  STAGIAIRE\n  PRESTATAIRE\n  DIRIGEANT\n  AUTRE\n}\n\nenum RhEmployeeStatus {\n  ACTIVE\n  ONBOARDING\n  OFFBOARDING\n  ARCHIVED\n}\n\nenum RhReglementStatus {\n  PENDING\n  SIGNED\n  WAIVED\n}\n\nenum RhContractType {\n  CDI\n  CDD\n  STAGE\n  PRESTA\n  AVENANT\n  AUTRE\n}\n\nenum RhContractStatus {\n  DRAFT\n  ACTIVE\n  ENDED\n  CANCELLED\n}\n\nenum RhLeaveType {\n  CONGES_PAYES\n  SANS_SOLDE\n  EXCEPTIONNEL\n  MALADIE\n  AUTRE\n}\n\nenum RhLeaveStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n}\n\nenum RhAbsenceStatus {\n  DECLARED\n  JUSTIFIED\n  UNJUSTIFIED\n}\n\nenum RhTimesheetStatus {\n  DRAFT\n  SUBMITTED\n  APPROVED\n  REJECTED\n}\n\nmodel RhEmployee {\n  id                       String            @id @default(cuid())\n  userId                   String?           @unique @db.Uuid\n  firstName                String\n  lastName                 String\n  /// Nom de naissance (si distinct).\n  birthName                String?\n  email                    String?\n  phone                    String?\n  personalEmail            String?\n  personalPhone            String?\n  jobTitle                 String?\n  department               String?\n  workLocation             String?\n  employeeCode             String?\n  employeeType             RhEmployeeType    @default(SALARIE)\n  status                   RhEmployeeStatus  @default(ACTIVE)\n  hireDate                 DateTime?         @db.Date\n  endDate                  DateTime?         @db.Date\n  birthDate                DateTime?         @db.Date\n  birthPlace               String?\n  nationality              String?\n  gender                   String?\n  idDocumentType           String?\n  idDocumentNumber         String?\n  idIssuedOn               DateTime?         @db.Date\n  idExpiresOn              DateTime?         @db.Date\n  idIssuedBy               String?\n  addressLine1             String?\n  addressLine2             String?\n  city                     String?\n  region                   String?\n  postalCode               String?\n  country                  String?           @default(\"Mali\")\n  emergencyContact         String?\n  emergencyContactName     String?\n  emergencyContactPhone    String?\n  emergencyContactRelation String?\n  bankName                 String?\n  bankAccountHolder        String?\n  /// IBAN / RIB — accès masqué côté UI collab.\n  bankIban                 String?\n  managerEmployeeId        String?\n  leaveBalanceDays         Decimal           @default(0) @db.Decimal(6, 2)\n  reglementStatus          RhReglementStatus @default(PENDING)\n  reglementSignedAt        DateTime?\n  /// Photo profil (GED Document) — mise à jour immédiate collab.\n  avatarDocumentId         String?\n  notes                    String?\n  createdAt                DateTime          @default(now())\n  updatedAt                DateTime          @updatedAt\n\n  user           User?                    @relation(\"RhEmployeeUser\", fields: [userId], references: [id], onDelete: SetNull)\n  manager        RhEmployee?              @relation(\"RhEmployeeManager\", fields: [managerEmployeeId], references: [id], onDelete: SetNull)\n  reports        RhEmployee[]             @relation(\"RhEmployeeManager\")\n  contracts      RhContract[]\n  leaves         RhLeaveRequest[]\n  absences       RhAbsence[]\n  timesheets     RhTimesheet[]\n  payslips       RhPayslip[]\n  inpsLines      RhInpsLine[]\n  profileChanges RhProfileChangeRequest[]\n  leaveMovements RhLeaveMovement[]\n\n  @@index([status, lastName])\n  @@index([managerEmployeeId])\n  @@map(\"rh_employees\")\n}\n\nenum RhProfileChangeStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n}\n\nmodel RhProfileChangeRequest {\n  id            String                @id @default(cuid())\n  employeeId    String\n  requesterId   String                @db.Uuid\n  status        RhProfileChangeStatus @default(PENDING)\n  note          String?\n  gedDocumentId String?\n  reviewedById  String?               @db.Uuid\n  reviewedAt    DateTime?\n  reviewNote    String?\n  createdAt     DateTime              @default(now())\n  updatedAt     DateTime              @updatedAt\n\n  employee   RhEmployee            @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  requester  User                  @relation(\"RhProfileChangeRequester\", fields: [requesterId], references: [id])\n  reviewedBy User?                 @relation(\"RhProfileChangeReviewer\", fields: [reviewedById], references: [id])\n  lines      RhProfileChangeLine[]\n\n  @@index([employeeId, status])\n  @@index([status, createdAt])\n  @@map(\"rh_profile_change_requests\")\n}\n\nmodel RhProfileChangeLine {\n  id        String  @id @default(cuid())\n  requestId String\n  fieldKey  String\n  oldValue  String?\n  newValue  String\n\n  request RhProfileChangeRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n\n  @@index([requestId])\n  @@map(\"rh_profile_change_lines\")\n}\n\n/// Catalogue administrable des types de congés / absences autorisées (réf. Mali + params MSK).\nmodel RhLeaveTypeConfig {\n  id                    String   @id @default(cuid())\n  /// Aligné sur RhLeaveType quand mappé (ex. CONGES_PAYES) ; codes étendus possibles.\n  code                  String   @unique\n  label                 String\n  legalBasis            String?\n  paid                  Boolean  @default(true)\n  impactsLeaveBalance   Boolean  @default(false)\n  requiresJustification Boolean  @default(false)\n  defaultDays           Decimal? @db.Decimal(5, 2)\n  active                Boolean  @default(true)\n  sortOrder             Int      @default(0)\n  notes                 String?\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n\n  @@index([active, sortOrder])\n  @@map(\"rh_leave_type_configs\")\n}\n\nenum RhLeaveMovementType {\n  OPENING_BALANCE\n  ACCRUAL\n  CONSUMPTION\n  ADJUSTMENT\n  CANCEL\n  SENIORITY_BONUS\n}\n\nmodel RhLeaveMovement {\n  id            String              @id @default(cuid())\n  employeeId    String\n  type          RhLeaveMovementType\n  days          Decimal             @db.Decimal(6, 2)\n  effectiveDate DateTime            @db.Date\n  sourceType    String?\n  sourceId      String?\n  note          String?\n  createdById   String?             @db.Uuid\n  createdAt     DateTime            @default(now())\n\n  employee  RhEmployee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  createdBy User?      @relation(\"RhLeaveMovementCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([employeeId, effectiveDate])\n  @@index([sourceType, sourceId])\n  @@map(\"rh_leave_movements\")\n}\n\nmodel RhWorkSchedule {\n  id           String   @id @default(cuid())\n  code         String   @unique\n  label        String\n  weeklyHours  Int      @default(40)\n  /// Jours ISO 1=lundi … 7=dimanche, JSON number[].\n  workDaysJson String   @default(\"[1,2,3,4,5]\")\n  startTime    String   @default(\"08:00\")\n  endTime      String   @default(\"17:00\")\n  breakStart   String   @default(\"13:00\")\n  breakEnd     String   @default(\"14:00\")\n  active       Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@map(\"rh_work_schedules\")\n}\n\nmodel RhPublicHoliday {\n  id        String   @id @default(cuid())\n  date      DateTime @db.Date\n  label     String\n  year      Int\n  createdAt DateTime @default(now())\n\n  @@unique([date])\n  @@index([year])\n  @@map(\"rh_public_holidays\")\n}\n\nmodel RhContract {\n  id            String           @id @default(cuid())\n  employeeId    String\n  type          RhContractType   @default(CDI)\n  status        RhContractStatus @default(DRAFT)\n  title         String\n  startDate     DateTime         @db.Date\n  endDate       DateTime?        @db.Date\n  salaryXof     Int?\n  notes         String?\n  gedDocumentId String?\n  parentId      String?\n  createdAt     DateTime         @default(now())\n  updatedAt     DateTime         @updatedAt\n\n  employee RhEmployee   @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  parent   RhContract?  @relation(\"RhContractAvenant\", fields: [parentId], references: [id], onDelete: SetNull)\n  avenants RhContract[] @relation(\"RhContractAvenant\")\n\n  @@index([employeeId, status])\n  @@map(\"rh_contracts\")\n}\n\nmodel RhLeaveRequest {\n  id            String        @id @default(cuid())\n  employeeId    String\n  requesterId   String        @db.Uuid\n  type          RhLeaveType   @default(CONGES_PAYES)\n  status        RhLeaveStatus @default(PENDING)\n  startDate     DateTime      @db.Date\n  endDate       DateTime      @db.Date\n  days          Decimal       @db.Decimal(5, 2)\n  reason        String?\n  validatedById String?       @db.Uuid\n  validatedAt   DateTime?\n  reviewNote    String?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  employee    RhEmployee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  requester   User       @relation(\"RhLeaveRequester\", fields: [requesterId], references: [id])\n  validatedBy User?      @relation(\"RhLeaveValidator\", fields: [validatedById], references: [id])\n\n  @@index([employeeId, status])\n  @@index([status, startDate])\n  @@map(\"rh_leave_requests\")\n}\n\nmodel RhAbsence {\n  id                String          @id @default(cuid())\n  employeeId        String\n  declaredById      String          @db.Uuid\n  status            RhAbsenceStatus @default(DECLARED)\n  startDate         DateTime        @db.Date\n  endDate           DateTime        @db.Date\n  reason            String\n  justificationNote String?\n  /// Justificatif GED (PDF / image) — optionnel à la déclaration.\n  gedDocumentId     String?\n  reviewedById      String?         @db.Uuid\n  reviewedAt        DateTime?\n  createdAt         DateTime        @default(now())\n  updatedAt         DateTime        @updatedAt\n\n  employee   RhEmployee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  declaredBy User       @relation(\"RhAbsenceDeclarer\", fields: [declaredById], references: [id])\n  reviewedBy User?      @relation(\"RhAbsenceReviewer\", fields: [reviewedById], references: [id])\n\n  @@index([employeeId, status])\n  @@map(\"rh_absences\")\n}\n\nmodel RhTimesheet {\n  id            String            @id @default(cuid())\n  employeeId    String\n  ownerId       String            @db.Uuid\n  weekStart     DateTime          @db.Date\n  status        RhTimesheetStatus @default(DRAFT)\n  totalMinutes  Int               @default(0)\n  note          String?\n  validatedById String?           @db.Uuid\n  validatedAt   DateTime?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  employee    RhEmployee        @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  owner       User              @relation(\"RhTimesheetOwner\", fields: [ownerId], references: [id])\n  validatedBy User?             @relation(\"RhTimesheetValidator\", fields: [validatedById], references: [id])\n  lines       RhTimesheetLine[]\n\n  @@unique([employeeId, weekStart])\n  @@index([status, weekStart])\n  @@map(\"rh_timesheets\")\n}\n\nmodel RhTimesheetLine {\n  id          String   @id @default(cuid())\n  timesheetId String\n  workDate    DateTime @db.Date\n  minutes     Int      @default(0)\n  label       String?\n\n  timesheet RhTimesheet @relation(fields: [timesheetId], references: [id], onDelete: Cascade)\n\n  @@index([timesheetId])\n  @@map(\"rh_timesheet_lines\")\n}\n\n// ─── Phase 5 — Paie + INPS ───\n\nenum RhPayrollPeriodStatus {\n  DRAFT\n  OPEN\n  CALCULATED\n  APPROVED\n  CLOSED\n}\n\nenum RhPayslipStatus {\n  DRAFT\n  CALCULATED\n  APPROVED\n  PAID\n  CANCELLED\n}\n\nenum RhInpsLineStatus {\n  DRAFT\n  CALCULATED\n  DECLARED\n  PAID\n}\n\n/// Paramètres cotisations (versionnés). ratesJson = [{code,label,rate,party}]\nmodel RhInpsSettings {\n  id                String   @id @default(cuid())\n  effectiveFrom     DateTime @db.Date\n  ratesJson         Json\n  declarationPeriod String   @default(\"monthly\")\n  paymentDueDay     Int      @default(15)\n  note              String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@index([effectiveFrom])\n  @@map(\"rh_inps_settings\")\n}\n\nmodel RhPayrollPeriod {\n  id           String                @id @default(cuid())\n  year         Int\n  month        Int\n  status       RhPayrollPeriodStatus @default(OPEN)\n  openedById   String                @db.Uuid\n  approvedById String?               @db.Uuid\n  approvedAt   DateTime?\n  closedAt     DateTime?\n  createdAt    DateTime              @default(now())\n  updatedAt    DateTime              @updatedAt\n\n  openedBy   User         @relation(\"RhPayrollOpener\", fields: [openedById], references: [id])\n  approvedBy User?        @relation(\"RhPayrollApprover\", fields: [approvedById], references: [id])\n  slips      RhPayslip[]\n  inpsLines  RhInpsLine[]\n\n  @@unique([year, month])\n  @@index([status, year, month])\n  @@map(\"rh_payroll_periods\")\n}\n\nmodel RhPayslip {\n  id                 String          @id @default(cuid())\n  periodId           String\n  employeeId         String\n  contractId         String?\n  status             RhPayslipStatus @default(DRAFT)\n  baseSalaryXof      Int\n  primesXof          Int             @default(0)\n  brutXof            Int\n  employeeDeductXof  Int             @default(0)\n  employerChargesXof Int             @default(0)\n  netXof             Int\n  gedDocumentId      String?\n  cptEntryId         String?\n  paidAt             DateTime?\n  paymentRef         String?\n  notes              String?\n  createdAt          DateTime        @default(now())\n  updatedAt          DateTime        @updatedAt\n\n  period   RhPayrollPeriod @relation(fields: [periodId], references: [id], onDelete: Cascade)\n  employee RhEmployee      @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  lines    RhPayslipLine[]\n  inpsLine RhInpsLine?\n\n  @@unique([periodId, employeeId])\n  @@index([employeeId, status])\n  @@map(\"rh_payslips\")\n}\n\nmodel RhPayslipLine {\n  id        String   @id @default(cuid())\n  payslipId String\n  code      String\n  label     String\n  kind      String\n  rate      Decimal? @db.Decimal(8, 6)\n  amountXof Int\n  sortOrder Int      @default(0)\n\n  payslip RhPayslip @relation(fields: [payslipId], references: [id], onDelete: Cascade)\n\n  @@index([payslipId])\n  @@map(\"rh_payslip_lines\")\n}\n\nmodel RhInpsLine {\n  id                      String           @id @default(cuid())\n  periodId                String\n  employeeId              String\n  payslipId               String?          @unique\n  baseAmountXof           Int\n  employeeContributionXof Int\n  employerContributionXof Int\n  status                  RhInpsLineStatus @default(DRAFT)\n  paymentRef              String?\n  declaredAt              DateTime?\n  paidAt                  DateTime?\n  createdAt               DateTime         @default(now())\n  updatedAt               DateTime         @updatedAt\n\n  period   RhPayrollPeriod @relation(fields: [periodId], references: [id], onDelete: Cascade)\n  employee RhEmployee      @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  payslip  RhPayslip?      @relation(fields: [payslipId], references: [id], onDelete: SetNull)\n\n  @@unique([periodId, employeeId])\n  @@index([status])\n  @@map(\"rh_inps_lines\")\n}\n\n/// Éligibilité paie / INPS / congés par type de contrat (activable).\nmodel RhContractTypeRule {\n  id               String         @id @default(cuid())\n  contractType     RhContractType @unique\n  includeInPayroll Boolean        @default(true)\n  applyInpsRates   Boolean        @default(true)\n  accruePaidLeave  Boolean        @default(true)\n  active           Boolean        @default(true)\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  @@map(\"rh_contract_type_rules\")\n}\n\n// ─── Phase 7A — Stocks ───\n\nenum StkMovementType {\n  ENTREE\n  SORTIE\n  AJUSTEMENT\n}\n\nmodel StkArticle {\n  id           String   @id @default(cuid())\n  code         String   @unique\n  family       String\n  subFamily    String?\n  designation  String\n  unit         String   @default(\"U\")\n  qtyOnHand    Decimal  @default(0) @db.Decimal(14, 3)\n  stockMin     Decimal  @default(0) @db.Decimal(14, 3)\n  location     String?\n  unitCostXof  Int?\n  observations String?\n  active       Boolean  @default(true)\n  createdById  String?  @db.Uuid\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  createdBy     User?             @relation(\"StkArticleCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  movements     StkMovement[]\n  purchaseLines StkPurchaseLine[]\n\n  @@index([family, active])\n  @@index([qtyOnHand, stockMin])\n  @@map(\"stk_articles\")\n}\n\nmodel StkMovement {\n  id          String          @id @default(cuid())\n  articleId   String\n  type        StkMovementType\n  quantity    Decimal         @db.Decimal(14, 3)\n  qtyBefore   Decimal         @db.Decimal(14, 3)\n  qtyAfter    Decimal         @db.Decimal(14, 3)\n  reason      String?\n  movedAt     DateTime        @default(now())\n  createdById String          @db.Uuid\n  createdAt   DateTime        @default(now())\n\n  article   StkArticle @relation(fields: [articleId], references: [id], onDelete: Restrict)\n  createdBy User       @relation(\"StkMovementCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  @@index([articleId, movedAt])\n  @@index([type, movedAt])\n  @@map(\"stk_movements\")\n}\n\n// ─── Phase 7B — Ops (achats, patrimoine, projets, anomalies) ───\n\nenum StkPurchaseStatus {\n  DRAFT\n  ORDERED\n  RECEIVED\n  CANCELLED\n}\n\nenum PatAssetStatus {\n  IN_SERVICE\n  MAINTENANCE\n  DISPOSED\n}\n\nenum PrjProjectStatus {\n  ACTIVE\n  ON_HOLD\n  DONE\n  CANCELLED\n}\n\nenum PrjExpenseStatus {\n  DRAFT\n  SUBMITTED\n  APPROVED\n  REJECTED\n  REIMBURSED\n}\n\nenum OpsTicketPriority {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum OpsTicketStatus {\n  TODO\n  IN_PROGRESS\n  DONE\n  DEFERRED\n}\n\nmodel StkPurchase {\n  id              String            @id @default(cuid())\n  number          String            @unique\n  supplierName    String\n  supplierContact String?\n  status          StkPurchaseStatus @default(DRAFT)\n  orderedAt       DateTime?\n  receivedAt      DateTime?\n  notes           String?\n  cptEntryId      String?\n  createdById     String            @db.Uuid\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n\n  createdBy User              @relation(\"StkPurchaseCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n  lines     StkPurchaseLine[]\n  assets    PatAsset[]\n\n  @@index([status, createdAt])\n  @@map(\"stk_purchases\")\n}\n\nmodel StkPurchaseLine {\n  id           String  @id @default(cuid())\n  purchaseId   String\n  articleId    String?\n  label        String\n  quantity     Decimal @db.Decimal(14, 3)\n  unitPriceXof Int\n  sortOrder    Int     @default(0)\n\n  purchase StkPurchase @relation(fields: [purchaseId], references: [id], onDelete: Cascade)\n  article  StkArticle? @relation(fields: [articleId], references: [id], onDelete: SetNull)\n\n  @@index([purchaseId])\n  @@map(\"stk_purchase_lines\")\n}\n\nmodel PatAsset {\n  id           String         @id @default(cuid())\n  code         String         @unique\n  designation  String\n  category     String\n  acquiredAt   DateTime       @db.Date\n  valueXof     Int\n  location     String?\n  status       PatAssetStatus @default(IN_SERVICE)\n  assignedToId String?        @db.Uuid\n  purchaseId   String?\n  amortYears   Int            @default(5)\n  disposeNote  String?\n  disposedAt   DateTime?\n  createdById  String         @db.Uuid\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n\n  assignedTo User?        @relation(\"PatAssetAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  createdBy  User         @relation(\"PatAssetCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n  purchase   StkPurchase? @relation(fields: [purchaseId], references: [id], onDelete: SetNull)\n\n  @@index([status, category])\n  @@map(\"pat_assets\")\n}\n\nmodel PrjProject {\n  id          String           @id @default(cuid())\n  code        String           @unique\n  name        String\n  description String?\n  status      PrjProjectStatus @default(ACTIVE)\n  budgetXof   Int              @default(0)\n  startDate   DateTime?        @db.Date\n  endDate     DateTime?        @db.Date\n  ownerId     String           @db.Uuid\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  owner    User         @relation(\"PrjProjectOwner\", fields: [ownerId], references: [id], onDelete: Restrict)\n  members  PrjMember[]\n  expenses PrjExpense[]\n\n  @@index([status])\n  @@map(\"prj_projects\")\n}\n\nmodel PrjMember {\n  id        String   @id @default(cuid())\n  projectId String\n  userId    String   @db.Uuid\n  role      String?\n  createdAt DateTime @default(now())\n\n  project PrjProject @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  user    User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, userId])\n  @@map(\"prj_members\")\n}\n\nmodel PrjExpense {\n  id               String           @id @default(cuid())\n  projectId        String\n  expenseDate      DateTime         @db.Date\n  nature           String\n  description      String?\n  plannedXof       Int              @default(0)\n  spentXof         Int\n  paymentMode      String?\n  status           PrjExpenseStatus @default(DRAFT)\n  justificatifNote String?\n  createdById      String           @db.Uuid\n  reviewedById     String?          @db.Uuid\n  reviewedAt       DateTime?\n  reviewNote       String?\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  project    PrjProject @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  createdBy  User       @relation(\"PrjExpenseCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n  reviewedBy User?      @relation(\"PrjExpenseReviewer\", fields: [reviewedById], references: [id], onDelete: SetNull)\n\n  @@index([projectId, status])\n  @@map(\"prj_expenses\")\n}\n\nmodel OpsTicket {\n  id           String            @id @default(cuid())\n  equipment    String\n  problem      String\n  priority     OpsTicketPriority @default(MEDIUM)\n  status       OpsTicketStatus   @default(TODO)\n  actionPlan   String?\n  observations String?\n  assignedToId String?           @db.Uuid\n  createdById  String            @db.Uuid\n  noticedAt    DateTime          @default(now())\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  assignedTo User? @relation(\"OpsTicketAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  createdBy  User  @relation(\"OpsTicketCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  @@index([status, priority])\n  @@index([assignedToId])\n  @@map(\"ops_tickets\")\n}\n\n// ─── Suivi tampon (isolé) ─────────────────────────────────────\n\nenum SvInvoiceStatus {\n  BROUILLON\n  EMISE\n  PARTIELLE\n  PAYEE\n  ANNULEE\n}\n\nenum SvCashDirection {\n  IN\n  OUT\n}\n\nenum SvStockMoveKind {\n  IN\n  OUT\n  ADJUST\n}\n\nmodel SvClient {\n  id          String   @id @default(cuid())\n  name        String\n  contactName String?\n  email       String?\n  phone       String?\n  city        String?\n  country     String?\n  notes       String?\n  sourceRef   String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  invoices  SvInvoice[]\n  contracts SvContractMeta[]\n  movements SvCashMovement[]\n\n  @@index([name])\n  @@map(\"sv_clients\")\n}\n\nmodel SvInvoice {\n  id             String          @id @default(cuid())\n  number         String?\n  legacyNumber   String?\n  status         SvInvoiceStatus @default(BROUILLON)\n  clientId       String\n  issuedAt       DateTime?\n  dueAt          DateTime?\n  totalHt        Int             @default(0)\n  totalVat       Int             @default(0)\n  totalTtc       Int             @default(0)\n  amountPaid     Int             @default(0)\n  currency       String          @default(\"XOF\")\n  vatRate        Int             @default(18)\n  object         String?\n  notes          String?\n  sourceDocument String?\n  remixedFromId  String?\n  createdById    String          @db.Uuid\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  client      SvClient         @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  remixedFrom SvInvoice?       @relation(\"SvInvoiceRemix\", fields: [remixedFromId], references: [id], onDelete: SetNull)\n  remixes     SvInvoice[]      @relation(\"SvInvoiceRemix\")\n  lines       SvInvoiceLine[]\n  payments    SvPayment[]\n  movements   SvCashMovement[]\n  createdBy   User             @relation(\"SvInvoiceCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  @@index([clientId, status])\n  @@index([number])\n  @@index([issuedAt])\n  @@map(\"sv_invoices\")\n}\n\nmodel SvInvoiceLine {\n  id          String  @id @default(cuid())\n  invoiceId   String\n  sortOrder   Int     @default(0)\n  label       String\n  description String?\n  qty         Int     @default(1)\n  unitPrice   Int     @default(0)\n  vatRate     Int?\n\n  invoice SvInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n  @@map(\"sv_invoice_lines\")\n}\n\nmodel SvPayment {\n  id        String   @id @default(cuid())\n  invoiceId String\n  amount    Int\n  paidAt    DateTime @default(now())\n  method    String?\n  reference String?\n  note      String?\n  createdAt DateTime @default(now())\n\n  invoice   SvInvoice        @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  movements SvCashMovement[]\n\n  @@index([invoiceId, paidAt])\n  @@map(\"sv_payments\")\n}\n\nmodel SvContractMeta {\n  id             String    @id @default(cuid())\n  clientId       String\n  title          String\n  partyName      String?\n  effectiveFrom  DateTime?\n  durationNote   String?\n  monthlyAmount  Int?\n  sourceDocument String?\n  gedDocumentId  String?\n  notes          String?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  client SvClient @relation(fields: [clientId], references: [id], onDelete: Cascade)\n\n  @@index([clientId])\n  @@map(\"sv_contracts\")\n}\n\nmodel SvCashMovement {\n  id              String          @id @default(cuid())\n  movedAt         DateTime\n  direction       SvCashDirection\n  amount          Int\n  category        String\n  description     String?\n  clientProject   String?\n  beneficiary     String?\n  paymentMethod   String?\n  paidBy          String?\n  reference       String?\n  linkedClientId  String?\n  linkedInvoiceId String?\n  linkedPaymentId String?\n  createdById     String          @db.Uuid\n  createdAt       DateTime        @default(now())\n\n  linkedClient  SvClient?  @relation(fields: [linkedClientId], references: [id], onDelete: SetNull)\n  linkedInvoice SvInvoice? @relation(fields: [linkedInvoiceId], references: [id], onDelete: SetNull)\n  linkedPayment SvPayment? @relation(fields: [linkedPaymentId], references: [id], onDelete: SetNull)\n  createdBy     User       @relation(\"SvCashMovementCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  @@index([movedAt])\n  @@index([direction, movedAt])\n  @@index([reference])\n  @@map(\"sv_cash_movements\")\n}\n\nmodel SvStockItem {\n  id           String   @id @default(cuid())\n  code         String   @unique\n  family       String\n  subFamily    String?\n  label        String\n  unit         String\n  quantity     Int      @default(0)\n  location     String?\n  observations String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  movements SvStockMovement[]\n\n  @@index([family])\n  @@map(\"sv_stock_items\")\n}\n\nmodel SvStockMovement {\n  id          String          @id @default(cuid())\n  itemId      String\n  movedAt     DateTime        @default(now())\n  kind        SvStockMoveKind\n  quantity    Int\n  note        String?\n  sourceRef   String?\n  createdById String          @db.Uuid\n  createdAt   DateTime        @default(now())\n\n  item      SvStockItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  createdBy User        @relation(\"SvStockMovementCreator\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  @@index([itemId, movedAt])\n  @@map(\"sv_stock_movements\")\n}\n",
